// Raw means "as it arrived": every value becomes text, nothing is trimmed or fixed.
// row_number is added by the Google Sheets node and is not a raw column.
const cfg = $('Init').first().json;
return $input.all().map(item => {
  const row = {};
  for (const [key, value] of Object.entries(item.json)) {
    if (key === 'row_number') continue;
    row[key] = value === null || value === undefined ? null : String(value);
  }
  row._run_id = cfg.run_id;
  return { json: row };
});

// One log row for this source. rows_read must equal rows_written, otherwise a batch failed quietly.
const cfg = $('Init').first().json;
const rowsRead = $('Prepare rows').all().length;
const rowsWritten = $input.all().length;
return [{ json: {
  run_id: cfg.run_id,
  agent: 'collection',
  action: 'load',
  source: cfg.source,
  target_table: `raw.${cfg.table}`,
  status: rowsRead === rowsWritten ? 'success' : 'warning',
  rows_read: rowsRead,
  rows_written: rowsWritten,
  duration_ms: Date.now() - cfg.started_at,
  reason: `Loaded ${cfg.label} (${cfg.type}) into raw.${cfg.table}`,
  details: JSON.stringify({ type: cfg.type, label: cfg.label }),
} }];

// Return one small item to the main workflow (never the loaded rows themselves)
const summary = $('Summarise').first().json;
const cfg = $('Init').first().json;
return [{ json: { ...summary, table: cfg.table, type: cfg.type, label: cfg.label, failed: false } }];
